#!/usr/bin/env node
/**
 * The Rebase Cloud price list the pricing page computes from is the control
 * plane's, exported — never typed. This checks that what is here is still
 * exactly what was exported, and has the shape the page reads.
 *
 *   src/data/cloud-prices.json   generated by the control plane's
 *                                backend/scripts/export-public-prices.ts
 *
 * Three failures:
 *   - the file's `contentHash` is not the sha256 of the rest of it: somebody
 *     edited a number by hand. Re-export it (see src/data/cloud-offer.ts).
 *   - a field the page reads is missing or the wrong type, or a region the
 *     flags can name has no prices: an export from an older control plane.
 *   - the per-unit rates the page shows (`src/data/cloud-unit-rates.mjs`,
 *     read back out of the sizes) do not reproduce every listed size to the
 *     cent: the page's "what each dial costs" table would disagree with the
 *     console.
 *
 * The hash is computed as the exporter computes it: JSON.stringify of a copy
 * with every object's keys sorted, no whitespace (`canonicalJson` in
 * backend/src/utils/public-prices.ts).
 *
 * Run: node scripts/check_cloud_prices.mjs
 */
import { createHash } from "node:crypto";
import { readFileSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { unitRateMismatches } from "../src/data/cloud-unit-rates.mjs";

const here = dirname(fileURLToPath(import.meta.url));
const file = resolve(here, "../src/data/cloud-prices.json");
const flagsFile = resolve(here, "../src/data/cloud-flags.ts");

const problems = [];
const fail = (msg) => problems.push(msg);

let doc;
try {
    doc = JSON.parse(readFileSync(file, "utf8"));
} catch (err) {
    console.error(`✗ ${file} is not readable JSON: ${err.message}`);
    process.exit(1);
}

function canonicalJson(value) {
    const sort = (v) => {
        if (Array.isArray(v)) return v.map(sort);
        if (v && typeof v === "object") {
            const out = {};
            for (const key of Object.keys(v).sort()) out[key] = sort(v[key]);
            return out;
        }
        return v;
    };
    return JSON.stringify(sort(value));
}

const { contentHash, ...rest } = doc;
const actual = createHash("sha256").update(canonicalJson(rest)).digest("hex");
if (contentHash !== actual) {
    fail(`contentHash ${contentHash} does not match the content (${actual}): the file was edited by hand. Re-export it from the control plane.`);
}

const isNum = (v) => typeof v === "number" && Number.isFinite(v) && v >= 0;
const isSize = (s) => s && typeof s.cpu === "string" && typeof s.memory === "string";

if (doc.schemaVersion !== 1) fail(`schemaVersion is ${doc.schemaVersion}; the page reads version 1`);
if (doc.currency !== "EUR") fail("currency is not EUR");
for (const path of ["platformFeeEur", "included.filesGb", "included.requestsPerMonth", "overage.filesEurPerGb", "overage.requestsEurPerMillion", "sleep.platformFeeEur", "sleep.hoursInMonth"]) {
    const v = path.split(".").reduce((o, k) => (o == null ? undefined : o[k]), doc);
    if (!isNum(v)) fail(`${path} is missing or not a number`);
}

const regions = doc.regions ?? {};
// Every region the flags file can name must be priced, or flipping the flag
// would render a page with no numbers.
const flags = readFileSync(flagsFile, "utf8");
const named = /export type RegionId = ([^;]+);/.exec(flags);
const regionIds = named ? [...named[1].matchAll(/"([^"]+)"/g)].map((m) => m[1]) : [];
if (regionIds.length === 0) fail("could not read RegionId from src/data/cloud-flags.ts");
for (const id of regionIds) {
    const r = regions[id];
    if (!r) {
        fail(`no prices for ${id}, which src/data/cloud-flags.ts can select`);
        continue;
    }
    for (const list of ["app", "database"]) {
        if (!Array.isArray(r[list]) || r[list].length === 0) fail(`${id}.${list} is empty`);
        else for (const s of r[list]) if (!isSize(s) || !isNum(s.monthlyEur)) fail(`${id}.${list} has a malformed size: ${JSON.stringify(s)}`);
    }
    if (!isNum(r.diskEurPerGib)) fail(`${id}.diskEurPerGib is missing`);
    if (!isSize(r.defaults?.app) || !isSize(r.defaults?.database) || !isNum(r.defaults?.diskGi)) fail(`${id}.defaults is malformed`);
    for (const ex of ["default", "smallest", "production", "sleeping"]) {
        if (!isNum(r.examples?.[ex]?.monthlyEur)) fail(`${id}.examples.${ex}.monthlyEur is missing`);
    }
    const s = r.examples?.sleeping;
    if (s && !(isNum(s.asleepMonthlyEur) && isNum(s.awakeHourEur) && isNum(s.alwaysOnMonthlyEur) && s.monthlyEur <= s.alwaysOnMonthlyEur)) {
        fail(`${id}.examples.sleeping is malformed or costs more than always-on`);
    }
    if (Array.isArray(r.app) && Array.isArray(r.database)) {
        for (const m of unitRateMismatches(r)) fail(`${id}: ${m}`);
    }
    if (typeof r.place !== "string" || typeof r.publicRegion !== "string") fail(`${id}.place / ${id}.publicRegion missing: an export from before saas 2026-11-2x`);
    const def = r.defaults;
    if (def && Array.isArray(r.app) && !r.app.some((a) => a.cpu === def.app.cpu && a.memory === def.app.memory)) fail(`${id}: the default app size is not among the offered sizes`);
    if (def && Array.isArray(r.database) && !r.database.some((d) => d.cpu === def.database.cpu && d.memory === def.database.memory)) fail(`${id}: the default database size is not among the offered sizes`);
}

if (problems.length > 0) {
    console.error(`✗ ${problems.length} problem(s) with src/data/cloud-prices.json:`);
    for (const p of problems) console.error(`  • ${p}`);
    process.exit(1);
}
console.log(`✓ cloud-prices.json matches its export (${actual.slice(0, 12)}…) and prices ${regionIds.join(", ")}`);
